Since the submit-threat-model action is not available, I'll build the threat model JSON based on the provided context and output it directly.

```json
{
  "schema": "redline.threatmodel.v1",
  "issueKey": "EVAL-03",
  "sketch": {
    "components": ["Tablet app", "SQLite database", "Offline sync mechanism", "Mobile device", "Patient notes cache"],
    "dataStores": ["SQLite database"],
    "externalServices": [],
    "trustBoundaries": ["Device physical boundary", "Network boundary"],
    "dataClasses": ["health"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Unencrypted patient data in local database",
      "scenario": "An attacker with physical access to the tablet extracts the SQLite database file and reads patient notes and medical history in cleartext. No encryption protects data at rest.",
      "component": "SQLite database",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "caches patient notes and medical history offline in a local SQLite database"
        }
      ],
      "asvs": ["V6.2.1", "V8.3.4"],
      "cwe": ["CWE-311", "CWE-312"],
      "plainLanguage": "Someone who gets hold of the tablet can copy the database and read all patient records stored on it",
      "requirement": {
        "title": "Encrypt patient data at rest",
        "given": "patient notes and medical history are cached offline",
        "when": "data is stored in the SQLite database",
        "then": "the database must be encrypted using AES-256 or equivalent"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Lost or stolen device exposes all cached records",
      "scenario": "A tablet is lost or stolen. The attacker gains access to all patient notes and medical history cached on the device without needing to bypass authentication since none is enforced at the device level.",
      "component": "Mobile device",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "Nurses use a tablet app that caches patient notes and medical history offline in a local SQLite database"
        }
      ],
      "asvs": ["V8.3.4", "V6.2.1"],
      "cwe": ["CWE-922"],
      "plainLanguage": "If the tablet is lost or stolen, whoever finds it can access all patient records on it",
      "requirement": {
        "title": "Require device unlock before accessing patient data",
        "given": "the tablet contains cached patient records",
        "when": "the device is powered on or woken from sleep",
        "then": "the user must authenticate with device PIN/biometric before accessing the app"
      }
    },
    {
      "stride": "Spoofing",
      "title": "No per-user authentication on shared devices",
      "scenario": "Since devices are shared between shifts and no authentication mechanism is specified, any nurse who picks up the tablet can access and modify patient data without proving their identity.",
      "component": "Tablet app",
      "likelihood": 5,
      "impact": 4,
      "evidence": [
        {
          "quote": "Devices are shared between shifts"
        }
      ],
      "asvs": ["V2.1.1", "V4.1.1"],
      "cwe": ["CWE-306"],
      "plainLanguage": "Any nurse who picks up the tablet can see and change patient notes without proving who they are",
      "requirement": {
        "title": "Require nurse authentication before data access",
        "given": "devices are shared between multiple nurses",
        "when": "a nurse wants to access patient data",
        "then": "they must authenticate with their personal credentials"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Patient data persists after shift ends",
      "scenario": "When a shift ends, patient data remains cached on the shared tablet. The next nurse can access patient records from the previous shift that they should not have access to, violating need-to-know principles.",
      "component": "Data lifecycle management",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "Devices are shared between shifts"
        },
        {
          "quote": "caches patient notes and medical history offline"
        }
      ],
      "asvs": ["V8.3.4", "V4.1.1"],
      "cwe": ["CWE-404"],
      "plainLanguage": "The next nurse who uses the tablet can see patient data left over from the previous nurse's shift",
      "requirement": {
        "title": "Clear cached data between sessions",
        "given": "a nurse's shift has ended",
        "when": "they log out or their session expires",
        "then": "their cached patient data must be securely deleted from the device"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No audit trail for offline data access",
      "scenario": "Since devices are shared and there's no mention of audit logging, there's no record of which nurse accessed which patient records while offline. If unauthorized access occurs, it cannot be detected or investigated.",
      "component": "Audit logging",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "Devices are shared between shifts"
        }
      ],
      "asvs": ["V7.1.1", "V7.2.1"],
      "cwe": ["CWE-778"],
      "plainLanguage": "There's no record of who looked at which patient files, so you can't tell if someone accessed records they shouldn't have",
      "requirement": {
        "title": "Log all patient data access offline",
        "given": "a nurse accesses patient data while offline",
        "when": "they view, create, or modify a patient record",
        "then": "the action must be logged locally and synced when connectivity is restored"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Access to all cached patients regardless of assignment",
      "scenario": "Without proper access controls, any nurse using the tablet can view all cached patient records, not just those assigned to them. This violates role-based access control and need-to-know principles.",
      "component": "Access control",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "Nurses use a tablet app that caches patient notes and medical history offline"
        }
      ],
      "asvs": ["V4.1.1", "V4.1.2"],
      "cwe": ["CWE-284"],
      "plainLanguage": "Nurses can see records for any patient stored on the tablet, even ones they're not assigned to care for",
      "requirement": {
        "title": "Enforce patient assignment access control",
        "given": "multiple patient records are cached on a device",
        "when": "a nurse attempts to access a patient record",
        "then": "access is granted only if that patient is assigned to the nurse"
      }
    },
    {
      "stride": "Tampering",
      "title": "Direct SQLite database modification",
      "scenario": "An attacker with physical device access or root privileges uses SQLite tools to directly modify patient notes in the database file, bypassing application logic and integrity checks.",
      "component": "SQLite database",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "caches patient notes and medical history offline in a local SQLite database"
        }
      ],
      "asvs": ["V8.3.3", "V5.1.3"],
      "cwe": ["CWE-345"],
      "plainLanguage": "Someone with device access could use database tools to change patient notes directly without going through the app",
      "requirement": {
        "title": "Implement database integrity protection",
        "given": "patient data is stored in SQLite",
        "when": "data is written or synced",
        "then": "cryptographic signatures or MACs must be stored to detect unauthorized modifications"
      }
    },
    {
      "stride": "Tampering",
      "title": "Malicious sync conflict to overwrite data",
      "scenario": "An attacker creates conflicting offline modifications to patient records. When syncing occurs, the conflict resolution logic is exploited to overwrite legitimate updates with attacker-controlled data.",
      "component": "Sync mechanism",
      "likelihood": 2,
      "impact": 4,
      "evidence": [
        {
          "quote": "Offline sync of patient notes"
        }
      ],
      "asvs": ["V8.3.3"],
      "cwe": ["CWE-345"],
      "plainLanguage": "An attacker could create fake conflicting changes that overwrite real patient notes when the device syncs",
      "requirement": {
        "title": "Secure conflict resolution with integrity checks",
        "given": "sync conflicts occur between offline and server data",
        "when": "conflicts are resolved",
        "then": "resolve based on authenticated timestamps and validate data integrity before accepting changes"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Corrupted database prevents access to critical data",
      "scenario": "SQLite database corruption due to improper shutdown, low storage, or malicious tampering prevents nurses from accessing cached patient data during critical care moments when network is unavailable.",
      "component": "SQLite database",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "caches patient notes and medical history offline in a local SQLite database"
        }
      ],
      "asvs": ["V1.1.1"],
      "cwe": ["CWE-404"],
      "plainLanguage": "If the database file gets corrupted, nurses lose access to patient records when working offline",
      "requirement": {
        "title": "Implement database backup and recovery",
        "given": "critical patient data is cached locally",
        "when": "the database becomes corrupted or inaccessible",
        "then": "the app must have a backup mechanism to restore or re-sync data"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Debug logs contain patient information",
      "scenario": "Application debug logs stored on the device include patient notes or medical history excerpts for troubleshooting. These logs are not encrypted and persist on the shared device.",
      "component": "Logging system",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "caches patient notes and medical history offline in a local SQLite database"
        }
      ],
      "asvs": ["V7.1.3"],
      "cwe": ["CWE-532"],
      "plainLanguage": "Error logs on the device might contain patient information that anyone with device access can read",
      "requirement": {
        "title": "Prevent logging of patient data",
        "given": "the app generates logs for debugging",
        "when": "logging any activity",
        "then": "patient notes, names, and medical history must never be written to logs"
      }
    }
  ]
}
```
